import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import NeuralPageWrapper from '../components/NeuralPageWrapper';
import NotificationToggle from '../components/NotificationToggle';

// Neural node component for visual effects
const NeuralNode = ({ x, y, size, pulseDelay, color }) => (
  <motion.div
    className="absolute rounded-full pointer-events-none"
    style={{
      left: `${x}%`,
      top: `${y}%`,
      width: `${size}px`,
      height: `${size}px`,
      backgroundColor: color || '#64C8FF',
      filter: 'blur(1px)'
    }}
    initial={{ opacity: 0 }}
    animate={{ 
      opacity: [0.2, 0.7, 0.2],
      boxShadow: [
        '0 0 2px rgba(100, 200, 255, 0.3)',
        '0 0 8px rgba(100, 200, 255, 0.6)',
        '0 0 2px rgba(100, 200, 255, 0.3)'
      ]
    }}
    transition={{
      duration: 2.5,
      repeat: Infinity,
      delay: pulseDelay
    }}
  />
);

const Profile = ({ studyData, tasks }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [profileData, setProfileData] = useState({
    name: 'Alex Johnson',
    email: 'alex.johnson@example.com',
    school: 'University of Technology',
    major: 'Computer Science',
    year: '3rd Year',
    bio: 'Dedicated student focusing on AI and machine learning. I enjoy problem-solving and building applications that make a difference.',
    avatar: 'https://via.placeholder.com/150/6366F1/FFFFFF?text=AJ'
  });
  
  // Enhanced item transition variant
  const itemVariants = {
    initial: { opacity: 0, y: 20 },
    animate: { 
      opacity: 1, 
      y: 0, 
      transition: { 
        type: "spring",
        stiffness: 300,
        damping: 25
      } 
    },
  };
  
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfileData(prev => ({
      ...prev,
      [name]: value
    }));
  };
  
  const handleSubmit = (e) => {
    e.preventDefault();
    setIsEditing(false);
    // In a real app, you would save the profile data to a database here
  };
  
  // Stats calculated from the passed studyData and tasks
  const totalStudyHours = studyData ? studyData.reduce((total, day) => total + day.value / 60, 0).toFixed(1) : 0;
  const completedTasks = tasks ? tasks.filter(task => task.completed).length : 0;
  const totalTasks = tasks ? tasks.length : 0;
  const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
  
  // Generate neural nodes for the background
  const nodes = useMemo(() => {
    const nodeArray = [];
    for (let i = 0; i < 20; i++) {
      nodeArray.push({
        x: Math.random() * 100,
        y: Math.random() * 100,
        size: 2 + Math.random() * 3,
        pulseDelay: Math.random() * 2
      });
    }
    return nodeArray;
  }, []);
  
  return (
    <NeuralPageWrapper
      title="Neural Profile"
      subtitle="Your synaptic connection to knowledge and progress"
    >
      <div className="relative">
        {/* Neural Background Effect */}
        <div className="absolute inset-0 pointer-events-none overflow-hidden">
          <motion.div
            className="absolute inset-0"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 1.5 }}
          >
            <svg className="w-full h-full opacity-10">
              <defs>
                <linearGradient id="neural-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#3B82F6" stopOpacity="0.6" />
                  <stop offset="100%" stopColor="#64C8FF" stopOpacity="0.6" />
                </linearGradient>
              </defs>
              <motion.g
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 1, delay: 0.5 }}
              >
                {Array.from({ length: 10 }).map((_, i) => (
                  <motion.path
                    key={`neural-path-${i}`}
                    d={`M${Math.random() * 100},${Math.random() * 100} Q${Math.random() * 100},${Math.random() * 100} ${Math.random() * 100},${Math.random() * 100}`}
                    stroke="url(#neural-gradient)"
                    strokeWidth="0.5"
                    fill="none"
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={{ pathLength: 1, opacity: 0.5 }}
                    transition={{ duration: 2, delay: i * 0.1 }}
                  />
                ))}
              </motion.g>
            </svg>
          </motion.div>
          
          {/* Background neural nodes */}
          {nodes.map((node, i) => (
            <NeuralNode 
              key={`bg-node-${i}`}
              x={node.x}
              y={node.y}
              size={node.size}
              pulseDelay={node.pulseDelay}
              color="rgba(100, 200, 255, 0.4)"
            />
          ))}
          
          {/* Scan line effect */}
          <motion.div 
            className="absolute h-0.5 w-full left-0"
            style={{ 
              background: 'linear-gradient(90deg, transparent, rgba(100, 200, 255, 0.5), transparent)',
              top: '0%'
            }}
            animate={{ 
              top: ['0%', '100%']
            }}
            transition={{ 
              duration: 8, 
              repeat: Infinity, 
              ease: "linear"
            }}
          />
        </div>
        
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 relative z-10">
          {/* Profile Card */}
          <motion.div 
            className="glass-panel rounded-xl overflow-hidden border border-neural-400/20 shadow-neural lg:col-span-2 relative"
            variants={itemVariants}
            initial="initial"
            animate="animate"
          >
            <motion.div 
              className="absolute top-0 left-0 w-full h-px"
              style={{
                background: 'linear-gradient(90deg, transparent, rgba(100, 200, 255, 0.5), transparent)'
              }}
              animate={{ 
                opacity: [0.2, 0.8, 0.2],
                width: ['0%', '100%', '0%']
              }}
              transition={{ duration: 4, repeat: Infinity }}
            />
            
            <div className="p-6">
              <div className="flex flex-col md:flex-row">
                <div className="md:mr-8 mb-4 md:mb-0 flex flex-col items-center relative">
                  {/* Neural nodes around avatar */}
                  {Array.from({ length: 5 }).map((_, i) => {
                    const angle = (i * Math.PI * 2) / 5;
                    return (
                      <motion.div
                        key={`avatar-node-${i}`}
                        className="absolute rounded-full bg-neural-400"
                        style={{
                          width: 4 + Math.random() * 3,
                          height: 4 + Math.random() * 3,
                          left: `calc(50% + ${35 * Math.cos(angle)}px)`,
                          top: `calc(50% + ${35 * Math.sin(angle)}px)`,
                          transform: 'translate(-50%, -50%)',
                          filter: 'blur(1px)'
                        }}
                        animate={{
                          opacity: [0.2, 0.8, 0.2],
                          boxShadow: [
                            '0 0 2px rgba(100, 200, 255, 0.3)',
                            '0 0 8px rgba(100, 200, 255, 0.6)',
                            '0 0 2px rgba(100, 200, 255, 0.3)'
                          ]
                        }}
                        transition={{
                          duration: 2 + Math.random() * 2,
                          repeat: Infinity,
                          delay: i * 0.4
                        }}
                      />
                    );
                  })}
                  
                  <div className="relative z-10">
                    <motion.div
                      className="relative"
                      whileHover={{ scale: 1.05 }}
                      transition={{ type: "spring", stiffness: 300, damping: 15 }}
                    >
                      <motion.div 
                        className="absolute -inset-1 rounded-full"
                        animate={{ 
                          boxShadow: [
                            '0 0 15px rgba(100, 200, 255, 0.3)',
                            '0 0 20px rgba(100, 200, 255, 0.6)',
                            '0 0 15px rgba(100, 200, 255, 0.3)'
                          ]
                        }}
                        transition={{ duration: 2, repeat: Infinity }}
                      />
                      
                      <img 
                        src={profileData.avatar} 
                        alt="Profile" 
                        className="rounded-full w-32 h-32 object-cover border-4 border-neural-500 relative z-10"
                      />
                      
                      {/* Animated neural ring */}
                      <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ transform: 'rotate(-90deg)' }}>
                        <motion.circle
                          cx="50%"
                          cy="50%"
                          r="36%" 
                          fill="none"
                          stroke="rgba(100, 200, 255, 0.5)"
                          strokeWidth="1"
                          strokeDasharray="1,6"
                          style={{ transform: 'translate(0, 0)' }}
                          animate={{ rotate: 360 }}
                          transition={{ 
                            duration: 20, 
                            repeat: Infinity, 
                            ease: "linear"
                          }}
                        />
                      </svg>
                      
                      {!isEditing && (
                        <motion.button
                          className="absolute bottom-0 right-0 bg-neural-500 text-white p-2 rounded-full shadow-lg z-20"
                          whileHover={{ scale: 1.1 }}
                          whileTap={{ scale: 0.9 }}
                          onClick={() => setIsEditing(true)}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                            <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                          </svg>
                        </motion.button>
                      )}
                    </motion.div>
                    
                    <div className="mt-4 text-center">
                      <motion.h3 
                        className="text-xl font-bold text-white"
                        initial={{ opacity: 0, y: 5 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.2 }}
                      >
                        {profileData.name}
                      </motion.h3>
                      <motion.p 
                        className="text-sm text-neural-200"
                        initial={{ opacity: 0, y: 5 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.3 }}
                      >
                        {profileData.email}
                      </motion.p>
                    </div>
                  </div>
                </div>
                
                <div className="flex-grow relative">
                  {isEditing ? (
                    <form onSubmit={handleSubmit}>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-medium mb-1 text-neural-200">
                            School
                          </label>
                          <input 
                            type="text" 
                            name="school"
                            value={profileData.school}
                            onChange={handleChange}
                            className="w-full px-3 py-2 bg-gray-700/50 border border-neural-400/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-neural-400/30"
                          />
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium mb-1 text-neural-200">
                            Major
                          </label>
                          <input 
                            type="text" 
                            name="major"
                            value={profileData.major}
                            onChange={handleChange}
                            className="w-full px-3 py-2 bg-gray-700/50 border border-neural-400/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-neural-400/30"
                          />
                        </div>
                        
                        <div>
                          <label className="block text-sm font-medium mb-1 text-neural-200">
                            Year
                          </label>
                          <input 
                            type="text" 
                            name="year"
                            value={profileData.year}
                            onChange={handleChange}
                            className="w-full px-3 py-2 bg-gray-700/50 border border-neural-400/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-neural-400/30"
                          />
                        </div>
                      </div>
                      
                      <div className="mt-4">
                        <label className="block text-sm font-medium mb-1 text-neural-200">
                          Bio
                        </label>
                        <textarea 
                          name="bio"
                          value={profileData.bio}
                          onChange={handleChange}
                          rows="4"
                          className="w-full px-3 py-2 bg-gray-700/50 border border-neural-400/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-neural-400/30"
                        ></textarea>
                      </div>
                      
                      <div className="flex justify-end mt-4">
                        <motion.button
                          type="button"
                          className="px-4 py-2 bg-gray-700 text-white rounded-lg mr-2"
                          whileHover={{ 
                            scale: 1.05,
                            backgroundColor: "rgba(55, 65, 81, 1)"
                          }}
                          whileTap={{ scale: 0.95 }}
                          onClick={() => setIsEditing(false)}
                        >
                          Cancel
                        </motion.button>
                        <motion.button
                          type="submit"
                          className="px-4 py-2 bg-neural-500 text-white rounded-lg relative overflow-hidden"
                          whileHover={{ 
                            scale: 1.05,
                            boxShadow: "0 0 15px rgba(100, 200, 255, 0.5)"
                          }}
                          whileTap={{ scale: 0.95 }}
                        >
                          <span className="relative z-10">Save</span>
                          <motion.div 
                            className="absolute inset-0 bg-gradient-to-r from-neural-400 to-neural-600 opacity-50"
                            animate={{ 
                              x: ['-100%', '100%'],
                              opacity: [0.3, 0.6, 0.3]
                            }}
                            transition={{ 
                              duration: 2, 
                              repeat: Infinity,
                              repeatType: "mirror"
                            }}
                          />
                        </motion.button>
                      </div>
                    </form>
                  ) : (
                    <>
                      <div className="flex justify-between items-center mb-4">
                        <motion.h3 
                          className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-neural-200 to-neural-400"
                          initial={{ opacity: 0, x: -20 }}
                          animate={{ opacity: 1, x: 0 }}
                          transition={{ delay: 0.2 }}
                        >
                          Personal Information
                        </motion.h3>
                        <motion.button
                          className="px-3 py-1.5 bg-neural-500 text-white rounded-lg flex items-center"
                          whileHover={{ 
                            scale: 1.05,
                            boxShadow: "0 0 10px rgba(100, 200, 255, 0.5)"
                          }}
                          whileTap={{ scale: 0.95 }}
                          onClick={() => setIsEditing(true)}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
                            <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                          </svg>
                          Edit
                        </motion.button>
                      </div>
                      
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                        <motion.div
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: 0.3 }}
                        >
                          <p className="text-sm text-neural-200">School</p>
                          <p className="text-white font-medium">{profileData.school}</p>
                        </motion.div>
                        
                        <motion.div
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: 0.4 }}
                        >
                          <p className="text-sm text-neural-200">Major</p>
                          <p className="text-white font-medium">{profileData.major}</p>
                        </motion.div>
                        
                        <motion.div
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: 0.5 }}
                        >
                          <p className="text-sm text-neural-200">Year</p>
                          <p className="text-white font-medium">{profileData.year}</p>
                        </motion.div>
                      </div>
                      
                      <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.6 }}
                      >
                        <p className="text-sm text-neural-200">Bio</p>
                        <p className="text-white">{profileData.bio}</p>
                      </motion.div>
                    </>
                  )}
                </div>
              </div>
            </div>
          </motion.div>
          
          {/* Stats Card */}
          <motion.div 
            className="glass-panel rounded-xl overflow-hidden border border-neural-400/20 shadow-neural"
            variants={itemVariants}
            initial="initial"
            animate="animate"
          >
            <motion.div 
              className="absolute top-0 left-0 w-full h-px"
              style={{
                background: 'linear-gradient(90deg, transparent, rgba(100, 200, 255, 0.5), transparent)'
              }}
              animate={{ 
                opacity: [0.2, 0.8, 0.2],
                width: ['0%', '100%', '0%']
              }}
              transition={{ duration: 4, repeat: Infinity, delay: 0.5 }}
            />
            
            <div className="p-6 relative">
              <motion.h3 
                className="text-xl font-bold mb-6 bg-clip-text text-transparent bg-gradient-to-r from-neural-200 to-neural-400"
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
              >
                Neural Stats
              </motion.h3>
              
              <div className="space-y-4">
                {/* Total Study Hours */}
                <div className="mb-6">
                  <div className="flex justify-between mb-1">
                    <span className="text-neural-200">Total Study Hours</span>
                    <span className="font-bold text-white">{totalStudyHours}h</span>
                  </div>
                  <div className="w-full h-3 bg-gray-700/50 rounded-full relative overflow-hidden">
                    <motion.div 
                      className="absolute h-full bg-gradient-to-r from-neural-600 to-neural-400 rounded-full"
                      initial={{ width: 0 }}
                      animate={{ width: `${Math.min(totalStudyHours / 50 * 100, 100)}%` }}
                      transition={{ 
                        type: "spring",
                        stiffness: 50,
                        damping: 15,
                        delay: 0.3
                      }}
                    >
                      {/* Inner glow effect */}
                      <motion.div 
                        className="absolute inset-0 bg-gradient-to-r from-transparent via-neural-200/30 to-transparent"
                        animate={{ 
                          x: ['-100%', '100%'] 
                        }}
                        transition={{ 
                          duration: 2, 
                          repeat: Infinity,
                          repeatDelay: 0.5,
                          ease: "easeInOut"
                        }}
                      />
                    </motion.div>
                    
                    {/* Neural nodes on the progress bar */}
                    <motion.div 
                      className="absolute top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-white shadow-glow-neural"
                      style={{ 
                        left: `${Math.min(totalStudyHours / 50 * 100, 100)}%`,
                        marginLeft: "-4px"
                      }}
                      animate={{ 
                        boxShadow: [
                          "0 0 2px rgba(100, 200, 255, 0.5)",
                          "0 0 10px rgba(100, 200, 255, 0.8)",
                          "0 0 2px rgba(100, 200, 255, 0.5)"
                        ] 
                      }}
                      transition={{ duration: 2, repeat: Infinity }}
                    />
                  </div>
                </div>
                
                {/* Tasks Completed */}
                <div className="mb-6">
                  <div className="flex justify-between mb-1">
                    <span className="text-neural-200">Tasks Completed</span>
                    <span className="font-bold text-white">{completedTasks}/{totalTasks}</span>
                  </div>
                  <div className="w-full h-3 bg-gray-700/50 rounded-full relative overflow-hidden">
                    <motion.div 
                      className="absolute h-full bg-gradient-to-r from-neural-600 to-neural-400 rounded-full"
                      initial={{ width: 0 }}
                      animate={{ width: `${completionRate}%` }}
                      transition={{ 
                        type: "spring",
                        stiffness: 50,
                        damping: 15,
                        delay: 0.4
                      }}
                    >
                      <motion.div 
                        className="absolute inset-0 bg-gradient-to-r from-transparent via-neural-200/30 to-transparent"
                        animate={{ 
                          x: ['-100%', '100%'] 
                        }}
                        transition={{ 
                          duration: 2, 
                          repeat: Infinity,
                          repeatDelay: 0.5,
                          ease: "easeInOut"
                        }}
                      />
                    </motion.div>
                    
                    <motion.div 
                      className="absolute top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-white shadow-glow-neural"
                      style={{ 
                        left: `${completionRate}%`,
                        marginLeft: "-4px"
                      }}
                      animate={{ 
                        boxShadow: [
                          "0 0 2px rgba(100, 200, 255, 0.5)",
                          "0 0 10px rgba(100, 200, 255, 0.8)",
                          "0 0 2px rgba(100, 200, 255, 0.5)"
                        ] 
                      }}
                      transition={{ duration: 2, repeat: Infinity, delay: 0.2 }}
                    />
                  </div>
                </div>
                
                {/* Study Efficiency */}
                <div className="mb-6">
                  <div className="flex justify-between mb-1">
                    <span className="text-neural-200">Study Efficiency</span>
                    <span className="font-bold text-white">76%</span>
                  </div>
                  <div className="w-full h-3 bg-gray-700/50 rounded-full relative overflow-hidden">
                    <motion.div 
                      className="absolute h-full bg-gradient-to-r from-neural-600 to-neural-400 rounded-full"
                      initial={{ width: 0 }}
                      animate={{ width: "76%" }}
                      transition={{ 
                        type: "spring",
                        stiffness: 50,
                        damping: 15,
                        delay: 0.5
                      }}
                    >
                      <motion.div 
                        className="absolute inset-0 bg-gradient-to-r from-transparent via-neural-200/30 to-transparent"
                        animate={{ 
                          x: ['-100%', '100%'] 
                        }}
                        transition={{ 
                          duration: 2, 
                          repeat: Infinity,
                          repeatDelay: 0.5,
                          ease: "easeInOut"
                        }}
                      />
                    </motion.div>
                    
                    <motion.div 
                      className="absolute top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-white shadow-glow-neural"
                      style={{ 
                        left: "76%",
                        marginLeft: "-4px"
                      }}
                      animate={{ 
                        boxShadow: [
                          "0 0 2px rgba(100, 200, 255, 0.5)",
                          "0 0 10px rgba(100, 200, 255, 0.8)",
                          "0 0 2px rgba(100, 200, 255, 0.5)"
                        ] 
                      }}
                      transition={{ duration: 2, repeat: Infinity, delay: 0.4 }}
                    />
                  </div>
                </div>
                
                {/* Focus Rating */}
                <div className="mb-6">
                  <div className="flex justify-between mb-1">
                    <span className="text-neural-200">Focus Rating</span>
                    <span className="font-bold text-white">83%</span>
                  </div>
                  <div className="w-full h-3 bg-gray-700/50 rounded-full relative overflow-hidden">
                    <motion.div 
                      className="absolute h-full bg-gradient-to-r from-neural-600 to-neural-400 rounded-full"
                      initial={{ width: 0 }}
                      animate={{ width: "83%" }}
                      transition={{ 
                        type: "spring",
                        stiffness: 50,
                        damping: 15,
                        delay: 0.6
                      }}
                    >
                      <motion.div 
                        className="absolute inset-0 bg-gradient-to-r from-transparent via-neural-200/30 to-transparent"
                        animate={{ 
                          x: ['-100%', '100%'] 
                        }}
                        transition={{ 
                          duration: 2, 
                          repeat: Infinity,
                          repeatDelay: 0.5,
                          ease: "easeInOut"
                        }}
                      />
                    </motion.div>
                    
                    <motion.div 
                      className="absolute top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-white shadow-glow-neural"
                      style={{ 
                        left: "83%",
                        marginLeft: "-4px"
                      }}
                      animate={{ 
                        boxShadow: [
                          "0 0 2px rgba(100, 200, 255, 0.5)",
                          "0 0 10px rgba(100, 200, 255, 0.8)",
                          "0 0 2px rgba(100, 200, 255, 0.5)"
                        ] 
                      }}
                      transition={{ duration: 2, repeat: Infinity, delay: 0.6 }}
                    />
                  </div>
                </div>
              </div>
              
              {/* Study Streak visualization */}
              <div className="mt-8">
                <div className="flex justify-between mb-2">
                  <span className="text-neural-200">Weekly Study Streak</span>
                  <span className="font-bold text-white">5 days</span>
                </div>
                
                <div className="flex justify-between space-x-1">
                  {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((day, i) => (
                    <motion.div 
                      key={day} 
                      className={`flex-1 h-10 rounded-md flex items-center justify-center text-xs font-medium relative overflow-hidden ${
                        i < 5 ? 'bg-neural-500/50 text-white' : 'bg-gray-700/30 text-gray-400'
                      }`}
                      initial={{ opacity: 0, scale: 0.8 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ delay: 0.3 + i * 0.1 }}
                      whileHover={i < 5 ? { 
                        scale: 1.05,
                        boxShadow: "0 0 8px rgba(100, 200, 255, 0.5)"
                      } : {}}
                    >
                      {i < 5 && (
                        <motion.div 
                          className="absolute inset-0 bg-gradient-to-r from-transparent via-neural-200/20 to-transparent"
                          animate={{ 
                            x: ['-100%', '100%'] 
                          }}
                          transition={{ 
                            duration: 2, 
                            repeat: Infinity,
                            repeatDelay: 1,
                            ease: "easeInOut",
                            delay: i * 0.2
                          }}
                        />
                      )}
                      <span className="relative z-10">{day}</span>
                    </motion.div>
                  ))}
                </div>
              </div>
            </div>
          </motion.div>
          
          {/* Notification Preferences Card */}
          <motion.div 
            className="glass-panel rounded-xl overflow-hidden border border-neural-400/20 shadow-neural lg:col-span-3"
            variants={itemVariants}
            initial="initial"
            animate="animate"
          >
            <motion.div 
              className="absolute top-0 left-0 w-full h-px"
              style={{
                background: 'linear-gradient(90deg, transparent, rgba(100, 200, 255, 0.5), transparent)'
              }}
              animate={{ 
                opacity: [0.2, 0.8, 0.2],
                width: ['0%', '100%', '0%']
              }}
              transition={{ duration: 4, repeat: Infinity, delay: 1 }}
            />
            
            <div className="p-6 relative">
              <motion.h3 
                className="text-xl font-bold mb-6 bg-clip-text text-transparent bg-gradient-to-r from-neural-200 to-neural-400"
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
              >
                Neural Network Preferences
              </motion.h3>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Preference toggle items with neural effects */}
                {[
                  { 
                    title: "Study Reminders", 
                    description: "Receive notifications for scheduled study sessions",
                    id: "study-reminders", 
                    defaultChecked: true 
                  },
                  { 
                    title: "Task Deadlines", 
                    description: "Get alerted when deadlines are approaching",
                    id: "task-deadlines", 
                    defaultChecked: true 
                  },
                  { 
                    title: "Progress Reports", 
                    description: "Weekly summary of your study progress",
                    id: "progress-reports", 
                    defaultChecked: false 
                  },
                  { 
                    title: "Neural UI Animations", 
                    description: "Enable or disable advanced UI animations",
                    id: "ui-animations", 
                    defaultChecked: true 
                  }
                ].map((pref, i) => (
                  <motion.div 
                    key={pref.id}
                    className="flex items-center justify-between p-4 bg-gray-800/30 rounded-lg border border-neural-400/10 relative overflow-hidden"
                    whileHover={{ 
                      backgroundColor: 'rgba(30, 41, 59, 0.5)',
                      borderColor: 'rgba(100, 200, 255, 0.3)',
                      transition: { duration: 0.2 }
                    }}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 + i * 0.1, type: "spring" }}
                  >
                    {/* Neural nodes in the background */}
                    {[...Array(3)].map((_, j) => (
                      <NeuralNode 
                        key={`pref-node-${i}-${j}`}
                        x={10 + j * 40}
                        y={Math.random() * 80 + 10}
                        size={2 + Math.random() * 2}
                        pulseDelay={j * 0.7}
                      />
                    ))}
                    
                    <div className="relative z-10">
                      <h4 className="font-medium text-white">{pref.title}</h4>
                      <p className="text-sm text-neural-200">{pref.description}</p>
                    </div>
                    <div className="relative z-10">
                      <NotificationToggle id={pref.id} defaultChecked={pref.defaultChecked} />
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </NeuralPageWrapper>
  );
};

export default Profile; 